1	import { useReducedMotion } from "framer-motion";
2	import { AgentGraph } from "./components/AgentGraph";
3	import { CommandBar } from "./components/CommandBar";
4	import { EquityCurves } from "./components/EquityCurves";
5	import { FooterMeters } from "./components/FooterMeters";
6	import { Objections } from "./components/Objections";
7	import { Panel } from "./components/Panel";
8	import { ReplayControls } from "./components/ReplayControls";
9	import { VerdictStamp } from "./components/VerdictStamp";
10	import { useAudit } from "./useAudit";
11	
12	// Demo ideas, exact text from AUDITOR_SPEC.md section 13.
13	export const DEMO_IDEAS = ["buy dips in an uptrend", "buy straddles on tech before earnings", "sell straddles on low-volatility mega-caps"];
14	
15	export default function App() {
16	  const a = useAudit();
17	  const reduced = useReducedMotion() ?? false;
18	  const state = a.state;
19	  const canResume = !!a.currentAuditId && state.phase !== "done";
20	  const elapsedMs = state.startedAt && state.lastTs ? Date.parse(state.lastTs) - Date.parse(state.startedAt) : 0;
21	  const reportUrl = a.currentAuditId && state.report ? `/api/audits/${encodeURIComponent(a.currentAuditId)}/report` : null;
22	
23	  return (
24	    <div className="grid h-full grid-rows-[auto_minmax(0,1fr)_auto_auto] gap-3 p-4">
25	      <CommandBar
26	        state={a.state}
27	        mode={a.mode}
28	        chips={DEMO_IDEAS}
29	        onSubmit={a.submitIdea}
30	        controls={
31	          <ReplayControls
32	            playing={a.playing}
33	            speed={a.speed}
34	            onPlay={a.resume}
35	            onPause={a.pause}
36	            onSpeed={a.setSpeed}
37	            disabled={!a.playing && !canResume}
38	          />
39	        }
40	      />
41	      <div className="grid min-h-0 grid-cols-[minmax(0,7fr)_minmax(0,9fr)_minmax(0,6fr)] gap-3">
42	        <Panel title="Agents" right={state.lastAgent && <span className="font-mono text-[11px] text-muted">{state.lastAgent}</span>}>
43	          <AgentGraph state={state} reduced={reduced} />
44	        </Panel>
45	        <Panel title="Evidence" right={state.equityRun && <span className="font-mono text-[11px] text-muted">run: {state.equityRun}</span>}>
46	          <EquityCurves state={state} reduced={reduced} />
47	        </Panel>
48	        <Panel title="Objections" right={state.followups.length > 0 && <span className="font-mono text-[11px] text-muted">follow-ups {state.followups.length}</span>}>
49	          <Objections state={state} reduced={reduced} />
50	        </Panel>
51	      </div>
52	      <div className="min-h-40">
53	        <VerdictStamp state={state} reduced={reduced} reportUrl={reportUrl} traceUrl={null} />
54	      </div>
55	      <FooterMeters state={state} elapsedMs={Number.isFinite(elapsedMs) ? elapsedMs : 0} followupsRun={state.followupsRun} />
56	      {a.state.errors.length > 0 && (
57	        <div role="alert" className="fixed right-4 bottom-16 max-w-md rounded border border-kill/60 bg-panel px-4 py-3 text-sm text-text shadow-lg">
58	          {a.state.errors[a.state.errors.length - 1]}
59	        </div>
60	      )}
61	    </div>
62	  );
63	}
