1	// Server-Sent Events client for /api/audits/{id}/events, plus the two small fetches.
2	import type { AuditEvent, AuditSummary } from "./events";
3	
4	export interface StreamOptions {
5	  replay: boolean;
6	  speed: number;
7	  from: number;
8	  onEvent: (e: AuditEvent) => void;
9	  onEnd: () => void;
10	  onError: (msg: string) => void;
11	}
12	
13	/** Open the event stream; returns a close function. The server sends `event: end` when done. */
14	export function openEvents(auditId: string, opts: StreamOptions): () => void {
15	  const q = new URLSearchParams({ speed: String(opts.speed), from: String(opts.from) });
16	  if (opts.replay) q.set("replay", "1");
17	  const es = new EventSource(`/api/audits/${encodeURIComponent(auditId)}/events?${q}`);
18	  let closed = false;
19	  const close = () => {
20	    if (!closed) {
21	      closed = true;
22	      es.close();
23	    }
24	  };
25	  es.onmessage = (m) => {
26	    try {
27	      opts.onEvent(JSON.parse(m.data) as AuditEvent);
28	    } catch {
29	      opts.onError("unreadable event line");
30	    }
31	  };
32	  es.addEventListener("end", () => {
33	    close();
34	    opts.onEnd();
35	  });
36	  es.onerror = () => {
37	    if (closed) return;
38	    close();
39	    opts.onError("event stream lost (is the server running on :8000?)");
40	  };
41	  return close;
42	}
43	
44	export async function listAudits(): Promise<AuditSummary[]> {
45	  const r = await fetch("/api/audits");
46	  if (!r.ok) throw new Error(`list failed: ${r.status}`);
47	  return (await r.json()) as AuditSummary[];
48	}
49	
50	export async function fetchReport(auditId: string): Promise<string> {
51	  const r = await fetch(`/api/audits/${encodeURIComponent(auditId)}/report`);
52	  if (!r.ok) throw new Error(`report failed: ${r.status}`);
53	  return r.text();
54	}
55

1	// Replay session: which audit plays, at what speed, paused or not. Live mode is stretch (spec 17).
2	import { useCallback, useEffect, useRef, useState } from "react";
3	import type { AuditSummary } from "./events";
4	import { initialState, reduce, type UiState } from "./state";
5	import { listAudits, openEvents } from "./stream";
6	
7	export const NO_RECORDING = "No recording for this idea. Record one with the auditor first.";
8	const SYNTHETIC_PREFIX = "SYNTHETIC FIXTURE";
9	const MIN_QUERY = 3;
10	
11	/** The development fixture labels itself through its idea text (scripts/synthetic_audit.py). */
12	export const isSynthetic = (idea: string): boolean => idea.startsWith(SYNTHETIC_PREFIX);
13	
14	/** Honesty label for the command bar and the stamp: synthetic fixture, fake-LLM run, or none for a real run. */
15	export function runLabel(idea: string, provider: string | null): string | null {
16	  if (isSynthetic(idea)) return "SYNTHETIC · NOT A REAL AUDIT";
17	  if (provider === "fake") return "FAKE LLM · KEYWORD PLANNER, REAL DATA";
18	  return null;
19	}
20	
21	/** The recording to play for a typed idea or chip: a real recording wins over the synthetic fixture. */
22	export function pickAudit(audits: AuditSummary[], text: string): AuditSummary | null {
23	  const t = text.trim().toLowerCase();
24	  if (t.length < MIN_QUERY) return null;
25	  const matches = audits.filter((a) => {
26	    const i = a.idea.toLowerCase();
27	    return i.includes(t) || t.includes(i);
28	  });
29	  return matches.find((a) => !isSynthetic(a.idea)) ?? matches[0] ?? null;
30	}
31	
32	export interface AuditSession {
33	  state: UiState;
34	  audits: AuditSummary[];
35	  mode: "replay" | "live";
36	  speed: number;
37	  setSpeed: (n: number) => void;
38	  playing: boolean;
39	  play: (auditId: string) => void;
40	  pause: () => void;
41	  resume: () => void;
42	  reset: () => void;
43	  currentAuditId: string | null;
44	  submitIdea: (text: string) => void;
45	}
46	
47	export function useAudit(): AuditSession {
48	  const [state, setState] = useState<UiState>(initialState);
49	  const [audits, setAudits] = useState<AuditSummary[]>([]);
50	  const [speed, setSpeedState] = useState(2);
51	  const [playing, setPlaying] = useState(false);
52	  const [currentAuditId, setCurrent] = useState<string | null>(null);
53	  const closeRef = useRef<(() => void) | null>(null);
54	  const stateRef = useRef(state);
55	  stateRef.current = state;
56	
57	  useEffect(() => {
58	    listAudits().then(setAudits).catch(() => setAudits([]));
59	    return () => closeRef.current?.();
60	  }, []);
61	
62	  const open = useCallback((auditId: string, from: number, spd: number) => {
63	    closeRef.current?.();
64	    closeRef.current = openEvents(auditId, {
65	      replay: true,
66	      speed: spd,
67	      from,
68	      onEvent: (e) => setState((s) => reduce(s, e)),
69	      onEnd: () => {
70	        closeRef.current = null;
71	        setPlaying(false);
72	      },
73	      onError: (msg) => {
74	        closeRef.current = null;
75	        setPlaying(false);
76	        setState((s) => ({ ...s, errors: [...s.errors, msg] }));
77	      },
78	    });
79	    setPlaying(true);
80	  }, []);
81	
82	  const play = useCallback(
83	    (auditId: string) => {
84	      setState(initialState);
85	      setCurrent(auditId);
86	      open(auditId, 0, speed);
87	    },
88	    [open, speed],
89	  );
90	
91	  const pause = useCallback(() => {
92	    closeRef.current?.();
93	    closeRef.current = null;
94	    setPlaying(false);
95	  }, []);
96	
97	  const resume = useCallback(() => {
98	    if (currentAuditId && stateRef.current.phase !== "done") open(currentAuditId, stateRef.current.lastSeq, speed);
99	  }, [currentAuditId, open, speed]);
100	
101	  const setSpeed = useCallback(
102	    (n: number) => {
103	      setSpeedState(n);
104	      if (playing && currentAuditId) open(currentAuditId, stateRef.current.lastSeq, n);
105	    },
106	    [playing, currentAuditId, open],
107	  );
108	
109	  const reset = useCallback(() => {
110	    pause();
111	    setState(initialState);
112	    setCurrent(null);
113	  }, [pause]);
114	
115	  const submitIdea = useCallback(
116	    (text: string) => {
117	      if (!text.trim()) return;
118	      const found = pickAudit(audits, text);
119	      if (found) play(found.audit_id);
120	      else setState((s) => ({ ...s, errors: [...s.errors, NO_RECORDING] }));
121	    },
122	    [audits, play],
123	  );
124	
125	  return { state, audits, mode: "replay", speed, setSpeed, playing, play, pause, resume, reset, currentAuditId, submitIdea };
126	}
127

1	// Audit event contract, AUDITOR_SPEC.md section 16. One JSON object per line of events.jsonl.
2	
3	export type Agent = "planner" | "researcher" | "mathematician" | "naysayer" | "reporter" | "triage";
4	export type Verdict = "kill" | "inconclusive" | "promising" | "cannot_audit";
5	
6	export interface Stats {
7	  n: number;
8	  blocks: number;
9	  win_rate: number;
10	  mean: number;
11	  median: number;
12	  ci_low: number;
13	  ci_high: number;
14	  worst_trade: number;
15	  worst_window: number;
16	}
17	export type BaselineStats = Stats & { paired_ci_low: number };
18	export type EquityPoint = [string, number];
19	
20	interface Base<T extends string, A extends Agent | null, P> {
21	  seq: number;
22	  ts: string;
23	  audit_id: string;
24	  type: T;
25	  agent: A;
26	  payload: P;
27	}
28	
29	export type AuditStartedEvent = Base<"audit_started", null, { idea: string; trace_id: string | null; llm_budget: number; fault: string | null; provider?: string }>;
30	export type AgentStartedEvent = Base<"agent_started", Agent, { step: string }>;
31	export type AgentFinishedEvent = Base<"agent_finished", Agent, { step: string; status: "ok" | "error"; duration_ms: number; summary: unknown }>;
32	export type LlmCallEvent = Base<"llm_call", Agent, { model: string; prompt_tokens: number; completion_tokens: number; cost_usd: number; latency_ms: number }>;
33	export type ToolCalledEvent = Base<"tool_called", Agent, { tool: string; args: unknown }>;
34	export type ToolResultEvent = Base<"tool_result", Agent, { tool: string; ok: boolean; duration_ms: number; summary: string }>;
