1	// Number formatting for the mono figures. Returns are fractions (0.012 = 1.2%).
2	export const pct = (x: number | undefined | null, digits = 2): string =>
3	  typeof x === "number" && Number.isFinite(x) ? `${x > 0 ? "+" : ""}${(x * 100).toFixed(digits)}%` : "–";
4	export const int = (n: number | undefined | null): string =>
5	  typeof n === "number" && Number.isFinite(n) ? Math.round(n).toLocaleString("en-US") : "–";
6	export const usd = (x: number): string => `$${x.toFixed(4)}`;
