1	// Agent graph: the section 4 loop as five nodes. Every animation marks an event:
2	// a node lights on agent_started, settles on agent_finished, a dot travels a link when work moves
3	// (links.key changes), and the return arc animates on each followup_requested.
4	import { motion } from "framer-motion";
5	import type { Agent } from "../events";
6	import { agentOrder, type AgentStatus, type UiState } from "../state";
7	
8	const W = 760, H = 420, NODE_W = 124, NODE_H = 64, Y = 190;
9	const X: Record<Agent, number> = { planner: 78, researcher: 229, mathematician: 380, naysayer: 531, reporter: 682, triage: 78 };
10	const LABEL: Record<Agent, string> = { planner: "Planner", researcher: "Researcher", mathematician: "Mathematician", naysayer: "Naysayer", reporter: "Reporter", triage: "Triage" };
11	const STROKE: Record<AgentStatus, string> = { idle: "var(--color-line)", active: "var(--color-accent)", done: "var(--color-promising)", error: "var(--color-kill)" };
12	const RETURN_ARC = `M ${X.naysayer} ${Y + NODE_H / 2} C ${X.naysayer} ${Y + 150}, ${X.mathematician} ${Y + 150}, ${X.mathematician} ${Y + NODE_H / 2}`;
13	
14	function linkPath(from: Agent, to: Agent): string {
15	  if (from === "naysayer" && to === "mathematician") return RETURN_ARC;
16	  const [a, b] = X[from] < X[to] ? [X[from] + NODE_W / 2, X[to] - NODE_W / 2] : [X[from] - NODE_W / 2, X[to] + NODE_W / 2];
17	  return `M ${a} ${Y} L ${b} ${Y}`;
18	}
19	
20	export function AgentGraph({ state, reduced }: { state: UiState; reduced: boolean }) {
21	  const followups = state.followups.length;
22	  return (
23	    <svg viewBox={`0 0 ${W} ${H}`} className="h-full w-full" role="img" aria-label="Agent pipeline">
24	      {/* forward chain */}
25	      {agentOrder.slice(0, -1).map((from, i) => {
26	        const to = agentOrder[i + 1];
27	        return <path key={from} d={linkPath(from, to)} stroke="var(--color-line)" strokeWidth={2} fill="none" />;
28	      })}
29	      {/* return arc: naysayer asks the mathematician for follow-ups */}
30	      <path d={RETURN_ARC} stroke={followups ? "var(--color-accent)" : "var(--color-line)"} strokeWidth={2} fill="none" strokeDasharray="6 6" opacity={followups ? 0.9 : 0.5} />
31	      <text x={(X.naysayer + X.mathematician) / 2} y={Y + 128} textAnchor="middle" className="font-mono" fontSize={11} fill={followups ? "var(--color-accent)" : "var(--color-muted)"}>
32	        follow-ups ×{followups}
33	      </text>
34	
35	      {/* travelling dot, remounted on every handoff */}
36	      {!reduced && state.links && (
37	        <circle key={state.links.key} r={5} fill="var(--color-accent)">
38	          <animateMotion dur="0.5s" path={linkPath(state.links.from, state.links.to)} fill="freeze" calcMode="spline" keySplines="0.16 1 0.3 1" keyTimes="0;1" />
39	        </circle>
40	      )}
41	
42	      {agentOrder.map((agent) => {
43	        const status = state.agents[agent];
44	        const active = status === "active";
45	        const x = X[agent] - NODE_W / 2, y = Y - NODE_H / 2;
46	        return (
47	          <g key={agent}>
48	            <motion.rect
49	              x={x} y={y} width={NODE_W} height={NODE_H} rx={6}
50	              fill="var(--color-bg)"
51	              stroke={STROKE[status]}
52	              strokeWidth={active ? 2 : 1.5}
53	              style={{ transformBox: "fill-box", transformOrigin: "center", filter: active && !reduced ? "drop-shadow(0 0 10px var(--color-accent))" : "none" }}
54	              animate={{ scale: active && !reduced ? 1.05 : 1 }}
55	              transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
56	            />
57	            <text x={X[agent]} y={Y - 4} textAnchor="middle" fontSize={15} fontWeight={600} fill={status === "idle" ? "var(--color-muted)" : "var(--color-text)"}>
58	              {LABEL[agent]}
59	            </text>
60	            <text x={X[agent]} y={Y + 18} textAnchor="middle" className="font-mono" fontSize={10} letterSpacing={1.5} fill={STROKE[status === "idle" ? "idle" : status]} style={{ textTransform: "uppercase" }}>
61	              {status === "idle" ? "standby" : status}
62	            </text>
63	            {agent === "researcher" && state.recoveries.map((r, i) => (
64	              <g key={i}>
65	                <rect x={X.researcher - 66} y={y - 30 - i * 22} width={132} height={18} rx={9} fill="var(--color-panel)" stroke={r.injected ? "var(--color-inconclusive)" : "var(--color-kill)"} />
66	                <text x={X.researcher} y={y - 17 - i * 22} textAnchor="middle" className="font-mono" fontSize={10} letterSpacing={1} fill={r.injected ? "var(--color-inconclusive)" : "var(--color-kill)"}>
67	                  <title>{`${r.failed}: ${r.action}`}</title>
68	                  {r.injected ? "RECOVERED · INJECTED" : "RECOVERED · REAL"}
69	                </text>
70	              </g>
71	            ))}
72	          </g>
73	        );
74	      })}
75	    </svg>
76	  );
77	}
