1	// Evidence panel: train and validation equity curves (lightweight-charts), the stats legend from the
2	// backtest_result event, and a baseline strip. Curves draw in over 600 ms when a result arrives.
3	import { ColorType, LineSeries, createChart, type IChartApi, type ISeriesApi } from "lightweight-charts";
4	import { useEffect, useRef } from "react";
5	import type { EquityPoint, Stats } from "../events";
6	import { int, pct } from "../fmt";
7	import type { UiState } from "../state";
8	import { toSeries } from "./equitySeries";
9	
10	const COLORS = { panel: "#2a1d14", line: "#46352a", muted: "#c2b280", accent: "#efe0b9" };
11	const DRAW_MS = 600;
12	
13	function Curve({ points, color, reduced }: { points: EquityPoint[]; color: string; reduced: boolean }) {
14	  const ref = useRef<HTMLDivElement>(null);
15	  const chartRef = useRef<IChartApi | null>(null);
16	  const seriesRef = useRef<ISeriesApi<"Line"> | null>(null);
17	
18	  useEffect(() => {
19	    const el = ref.current;
20	    if (!el) return;
21	    const chart = createChart(el, {
22	      autoSize: true,
23	      layout: { background: { type: ColorType.Solid, color: COLORS.panel }, textColor: COLORS.muted, fontFamily: "JetBrains Mono", fontSize: 11, attributionLogo: false },
24	      grid: { vertLines: { color: COLORS.line }, horzLines: { color: COLORS.line } },
25	      rightPriceScale: { borderColor: COLORS.line },
26	      timeScale: { borderColor: COLORS.line, timeVisible: false },
27	      crosshair: { horzLine: { color: COLORS.muted }, vertLine: { color: COLORS.muted } },
28	      handleScroll: false,
29	      handleScale: false,
30	    });
31	    const series = chart.addSeries(LineSeries, {
32	      color, lineWidth: 2, priceLineVisible: false, lastValueVisible: true, crosshairMarkerVisible: false,
33	      priceFormat: { type: "custom", formatter: (v: number) => pct(v, 1), minMove: 0.001 },
34	    });
35	    chartRef.current = chart;
36	    seriesRef.current = series;
37	    return () => {
38	      chart.remove();
39	      chartRef.current = null;
40	      seriesRef.current = null;
41	    };
42	  }, [color]);
43	
44	  useEffect(() => {
45	    const series = seriesRef.current, chart = chartRef.current;
46	    if (!series || !chart) return;
47	    const data = toSeries(points);
48	    if (data.length === 0 || reduced) {
49	      series.setData(data);
50	      chart.timeScale().fitContent();
51	      return;
52	    }
53	    let raf = 0;
54	    const start = performance.now();
55	    const step = (now: number) => {
56	      const p = Math.min(1, (now - start) / DRAW_MS);
57	      series.setData(data.slice(0, Math.max(1, Math.round(p * data.length))));
58	      chart.timeScale().fitContent();
59	      if (p < 1) raf = requestAnimationFrame(step);
60	    };
61	    raf = requestAnimationFrame(step);
62	    return () => cancelAnimationFrame(raf);
63	  }, [points, reduced]);
64	
65	  return <div ref={ref} className="h-full min-h-0 w-full" />;
66	}
67	
68	function Legend({ label, stats, color }: { label: string; stats: Stats | null; color: string }) {
69	  return (
70	    <div className="flex flex-wrap items-baseline gap-x-3 gap-y-0.5 font-mono text-[11px]">
71	      <span className="font-semibold tracking-[0.14em]" style={{ color }}>{label}</span>
72	      {stats ? (
73	        <>
74	          <span className="text-muted">n <span className="text-text">{int(stats.n)}</span></span>
75	          <span className="text-muted">mean <span className="text-text">{pct(stats.mean)}</span></span>
76	          <span className="text-muted">95% <span className="text-text">[{pct(stats.ci_low)}, {pct(stats.ci_high)}]</span></span>
77	          <span className="text-muted">win <span className="text-text">{(stats.win_rate * 100).toFixed(0)}%</span></span>
78	        </>
79	      ) : (
80	        <span className="text-muted">waiting for backtest</span>
81	      )}
82	    </div>
83	  );
84	}
