86	function BaselineStrip({ stats }: { stats: NonNullable<UiState["stats"]> }) {
87	  const rows = [
88	    { label: "v0 validation mean", value: stats.validation.mean, color: COLORS.accent },
89	    { label: "no-condition baseline", value: stats.baseline.mean, color: COLORS.muted },
90	  ];
91	  const max = Math.max(...rows.map((r) => Math.abs(r.value)), 1e-9);
92	  const paired = stats.baseline.paired_ci_low;
93	  return (
94	    <div className="grid grid-cols-[auto_1fr_auto] items-center gap-x-4 gap-y-1 border-t border-line pt-3 font-mono text-[11px]">
95	      {rows.map((r) => (
96	        <div key={r.label} className="contents">
97	          <span className="text-muted">{r.label}</span>
98	          <svg viewBox="0 0 200 10" preserveAspectRatio="none" className="h-2.5 w-full" aria-hidden>
99	            <line x1={100} y1={0} x2={100} y2={10} stroke={COLORS.line} />
100	            <rect x={r.value < 0 ? 100 - (Math.abs(r.value) / max) * 98 : 100} y={2} width={(Math.abs(r.value) / max) * 98} height={6} fill={r.color} />
101	          </svg>
102	          <span className="text-right text-text">{pct(r.value)}</span>
103	        </div>
104	      ))}
105	      <span className="col-span-3 pt-1 text-muted">
106	        paired lower bound (v0 minus baseline, 2.5th pct) <span style={{ color: paired > 0 ? "var(--color-promising)" : "var(--color-inconclusive)" }}>{pct(paired)}</span>
107	      </span>
108	    </div>
109	  );
110	}
