1	// Objections panel (spec 16, item 5): the Naysayer's coded checks and its follow-ups, one card per event.
2	// Motion, all one-shot and tied to an event: a card lands (drops 10 px, settles from 102%, 320 ms, no bounce) and its
3	// border settles from the accent to its resting colour (600 ms) when its check_result or followup_requested arrives;
4	// a follow-up's result line and status badge appear when its backtest_result lands, and the badge changes once more
5	// when the verdict says whether the downgrade was applied. Reduced motion: opacity only, 150 ms.
6	import { motion } from "framer-motion";
7	import { useEffect, useRef } from "react";
8	import { appliedDowngrade, type Followup, type UiState } from "../state";
9	
10	const EASE = [0.16, 1, 0.3, 1] as const;
11	// Hex copies of the index.css tokens: Framer can interpolate hex colours, not var() strings.
12	const HEX = { line: "#46352a", accent: "#efe0b9", amber: "#e2a548" };
13	
14	const CHECK_LABEL: Record<string, string> = {
15	  evidence: "Evidence", leakage: "Leakage", decay: "Out-of-sample decay", shared_window: "Shared window",
16	  cost_realism: "Cost realism", tail_risk: "Tail risk", data_drops: "Data drops",
17	};
18	// The follow-up menu names from spec section 4, shown until the result's own title arrives.
19	const FOLLOWUP_TITLE: Record<string, string> = { F1: "Earnings excluded", F2: "Per-year stability", F3: "Horizon sensitivity", F4: "Concentration" };
20	
21	function landing(reduced: boolean, rest: string) {
22	  return reduced
23	    ? { initial: { opacity: 0, borderColor: rest }, animate: { opacity: 1, borderColor: rest }, transition: { duration: 0.15 } }
24	    : {
25	        initial: { opacity: 0, y: -10, scale: 1.02, borderColor: HEX.accent },
26	        animate: { opacity: 1, y: 0, scale: 1, borderColor: rest },
27	        transition: { duration: 0.32, ease: EASE, borderColor: { duration: 0.6, ease: EASE } },
28	      };
29	}
30	
31	/** Keeps a card that just landed or changed visible when the panel scrolls (1280×800). Instant on purpose: the
32	 *  card's own landing is the motion, and smooth scrolls cancel each other when events arrive close together. */
33	function useInView<T extends HTMLElement>(dep: unknown) {
34	  const ref = useRef<T>(null);
35	  useEffect(() => {
36	    ref.current?.scrollIntoView?.({ block: "nearest" });
37	  }, [dep]);
38	  return ref;
39	}
40	
41	function Heading({ children }: { children: string }) {
42	  return <h3 className="mb-2 font-mono text-[10px] uppercase tracking-[0.18em] text-muted">{children}</h3>;
43	}
44	
45	function CheckCard({ c, reduced }: { c: UiState["checks"][number]; reduced: boolean }) {
46	  const ref = useInView<HTMLLIElement>(null);
47	  const label = CHECK_LABEL[c.check] ?? c.check.replace(/_/g, " ");
48	  return (
49	    <motion.li ref={ref} {...landing(reduced, c.passed ? HEX.line : HEX.amber)} className="rounded border bg-bg px-3 py-1" title={c.note}>
