51	        <span className={`w-8 shrink-0 font-mono text-[10px] font-semibold tracking-[0.14em] ${c.passed ? "text-promising" : "text-inconclusive"}`}>
52	          {c.passed ? "PASS" : "FAIL"}
53	        </span>
54	        <span className="shrink-0 text-[13px] font-medium text-text">{label}</span>
55	        {/* Passed checks stay one quiet line; a failed check is an objection, so its note shows in full. */}
56	        {c.passed && <span className="min-w-0 truncate text-xs text-muted">{c.note}</span>}
