63	function badge(f: Followup, verdict: UiState["verdict"]): { text: string; tone: "muted" | "amber" | "applied"; title?: string } {
64	  if (f.result === undefined && f.downgrade === undefined) return { text: "REQUESTED", tone: "muted" };
65	  if (f.skipped) return { text: "SKIPPED", tone: "muted" };
66	  if (!f.downgrade) return { text: "NO DOWNGRADE", tone: "muted" };
67	  // The rule text (cause) goes in the tooltip: the verdict stamp already lists every applied downgrade's cause.
68	  const rule = f.cause ? `rule: ${f.cause}` : "rule met";
69	  if (!verdict) return { text: "RULE MET", tone: "amber", title: rule };
70	  const applied = appliedDowngrade(f, verdict);
71	  if (applied) return { text: "RULE MET · APPLIED", tone: "applied", title: `${rule}\n${applied.from ?? "?"} → ${applied.to ?? "?"}` };
72	  return { text: "RULE MET · NOT APPLIED", tone: "muted", title: `${rule}\nfollow-ups only downgrade a promising verdict (verdict: ${verdict.verdict})` };
73	}
