84	  const enter = reduced ? { opacity: 0 } : { opacity: 0, y: 4 };
85	  return (
86	    <motion.li ref={ref} {...landing(reduced, f.downgrade ? HEX.amber : HEX.line)} className="rounded border bg-bg px-3 py-2">
