90	          <span className="truncate text-[13px] font-medium text-text">{f.title ?? FOLLOWUP_TITLE[f.id] ?? "follow-up"}</span>
91	        </div>
92	        <motion.span
93	          key={b.text}
94	          initial={{ opacity: 0 }}
95	          animate={{ opacity: 1 }}
96	          transition={{ duration: reduced ? 0.15 : 0.2, ease: EASE }}
97	          title={b.title}
98	          className={`shrink-0 rounded-full border px-2 py-0.5 font-mono text-[10px] font-semibold tracking-[0.12em] ${TONE[b.tone]}`}
99	        >
100	          {b.text}
101	        </motion.span>
102	      </div>
103	      {f.reason && (
104	        <p className="mt-1 text-xs text-muted">
105	          <span className="font-mono text-[10px] uppercase tracking-[0.14em]">why </span>
106	          {f.reason}
107	        </p>
108	      )}
109	      {f.result !== undefined && (
