118	export function Objections({ state, reduced }: { state: UiState; reduced: boolean }) {
119	  const { checks, followups, verdict } = state;
120	  if (checks.length === 0 && followups.length === 0) {
121	    return <p className="font-mono text-[11px] text-muted">{state.phase === "idle" ? "no audit loaded" : "waiting for the Naysayer"}</p>;
122	  }
