1	// Verdict stamp: lands on the verdict event (the one long animation, 900 ms), headline figures count
2	// up from zero. Copy for the subtitles is fixed by AUDITOR_SPEC.md sections 1 and 9.
3	import { motion } from "framer-motion";
4	import { useEffect, useRef } from "react";
5	import type { Verdict } from "../events";
6	import { int, pct } from "../fmt";
7	import type { UiState } from "../state";
8	import { runLabel } from "../useAudit";
9	import { countUp } from "./countUp";
10	
11	const STAMP: Record<Verdict, { label: string; color: string }> = {
12	  kill: { label: "KILLED", color: "var(--color-kill)" },
13	  inconclusive: { label: "INCONCLUSIVE", color: "var(--color-inconclusive)" },
14	  promising: { label: "PROMISING", color: "var(--color-promising)" },
15	  cannot_audit: { label: "CANNOT AUDIT", color: "var(--color-cannot)" },
16	};
17	const SUBTITLE: Partial<Record<Verdict, string>> = {
18	  promising: "Passed a 6-month historical screen. Not a forecast. Not financial advice.",
19	  inconclusive: "inconclusive: a strategy with no real edge lands here about half the time",
20	};
21	const REVEAL_MS = 900;
22	
23	function Figure({ label, value, format, reduced }: { label: string; value: number | undefined; format: (v: number) => string; reduced: boolean }) {
24	  const ref = useRef<HTMLSpanElement>(null);
25	  useEffect(() => {
26	    const el = ref.current;
27	    if (!el || typeof value !== "number") return;
28	    return countUp(0, value, reduced ? 0 : REVEAL_MS, (v) => {
29	      el.textContent = format(v);
30	    });
31	  }, [value, format, reduced]);
32	  return (
33	    <div className="flex flex-col">
34	      <span className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted">{label}</span>
35	      <span ref={ref} className="font-mono text-2xl font-semibold tabular-nums text-text">{typeof value === "number" ? format(0) : "–"}</span>
36	    </div>
37	  );
38	}
39	
40	export function VerdictStamp({ state, reduced, reportUrl, traceUrl }: { state: UiState; reduced: boolean; reportUrl: string | null; traceUrl: string | null }) {
41	  const v = state.verdict;
42	  if (!v) {
43	    return (
44	      <div className="flex h-full items-center justify-center rounded-md border border-dashed border-line font-mono text-xs tracking-[0.2em] text-muted">
45	        {state.phase === "running" ? "VERDICT PENDING" : "NO AUDIT LOADED"}
46	      </div>
47	    );
48	  }
49	  const stamp = STAMP[v.verdict] ?? STAMP.cannot_audit;
50	  const showFigures = v.verdict !== "cannot_audit";
51	  return (
52	    <motion.div
53	      key={v.verdict}
54	      initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 1.15, rotate: -3 }}
55	      animate={{ opacity: 1, scale: 1, rotate: 0 }}
56	      transition={{ duration: REVEAL_MS / 1000, ease: [0.16, 1, 0.3, 1] }}
57	      className="grid h-full grid-cols-[auto_1fr_auto] items-center gap-8 rounded-md border-2 px-6 py-4"
58	      style={{ borderColor: stamp.color, background: `color-mix(in srgb, ${stamp.color} 8%, var(--color-panel))` }}
59	      role="status"
60	    >
61	      <div className="flex flex-col">
62	        <span className="font-sans text-5xl font-semibold tracking-[0.08em]" style={{ color: stamp.color }}>{stamp.label}</span>
63	        {SUBTITLE[v.verdict] && <span className="mt-1 max-w-md text-sm text-muted">{SUBTITLE[v.verdict]}</span>}
64	        {runLabel(state.idea, state.provider) && <span className="mt-1 font-mono text-[11px] tracking-[0.14em] text-kill">{runLabel(state.idea, state.provider)}</span>}
65	      </div>
66	      <div className="flex min-w-0 flex-col gap-3">
67	        <p className="text-sm text-text">{v.reason}</p>
68	        {showFigures && (
69	          <div className="grid grid-cols-4 gap-6">
70	            <Figure label="validation trades" value={v.headline.n} format={int} reduced={reduced} />
71	            <Figure label="mean per trade" value={v.headline.mean} format={pct} reduced={reduced} />
72	            <Figure label="lower bound" value={v.headline.ci_low} format={pct} reduced={reduced} />
73	            <Figure label="paired lower bound" value={v.headline.paired_ci_low} format={pct} reduced={reduced} />
74	          </div>
75	        )}
76	        {v.downgrades.length > 0 && (
77	          <ul className="flex flex-wrap gap-2 font-mono text-[11px]">
78	            {v.downgrades.map((d, i) => (
79	              <li key={i} title={typeof d.cause === "string" ? d.cause : undefined} className="max-w-full truncate rounded-full border border-inconclusive/60 px-2 py-0.5 text-inconclusive">
80	                downgrade: {typeof d.cause === "string" ? d.cause : JSON.stringify(d)}
81	              </li>
82	            ))}
83	          </ul>
84	        )}
85	      </div>
86	      <div className="flex flex-col gap-2 font-mono text-xs">
87	        <a
88	          href={reportUrl ?? "#"}
89	          target="_blank"
90	          rel="noreferrer"
91	          aria-disabled={!reportUrl}
92	          className={`rounded border border-line px-3 py-1.5 text-center transition-colors duration-150 ${reportUrl ? "text-text hover:border-accent" : "pointer-events-none text-muted opacity-50"}`}
93	        >
94	          Report
95	        </a>
96	        <a
97	          href={traceUrl ?? "#"}
98	          target="_blank"
99	          rel="noreferrer"
100	          aria-disabled={!traceUrl}
101	          title={traceUrl ? "Open the neatlogs trace" : "trace URL format to be verified"}
102	          className={`rounded border border-line px-3 py-1.5 text-center transition-colors duration-150 ${traceUrl ? "text-text hover:border-accent" : "pointer-events-none text-muted opacity-50"}`}
103	        >
104	          neatlogs trace
105	        </a>
106	      </div>
107	    </motion.div>
108	  );
109	}
