1	/** Tween a number from `from` to `to` over `ms` with requestAnimationFrame; returns a cancel function.
2	 *  Jumps straight to `to` when ms <= 0 or when requestAnimationFrame is unavailable (tests, reduced motion). */
3	export function countUp(from: number, to: number, ms: number, onFrame: (v: number) => void): () => void {
4	  if (ms <= 0 || typeof requestAnimationFrame === "undefined") {
5	    onFrame(to);
6	    return () => {};
7	  }
8	  const start = performance.now();
9	  let raf = 0;
10	  const step = (now: number) => {
11	    const p = Math.min(1, (now - start) / ms);
12	    const eased = 1 - Math.pow(1 - p, 3);
13	    onFrame(from + (to - from) * eased);
14	    if (p < 1) raf = requestAnimationFrame(step);
15	  };
16	  raf = requestAnimationFrame(step);
17	  return () => cancelAnimationFrame(raf);
18	}
